import React, { useState, useEffect } from 'react';
import './EquipmentForm.css';
import { inferType } from '../services/api';

function EquipmentForm({ equipment, onSubmit, onCancel }) {
  const [name, setName] = useState('');
  const [type, setType] = useState('');
  const [status, setStatus] = useState('Active');
  const [lastCleanedDate, setLastCleanedDate] = useState('');
  const [isInferred, setIsInferred] = useState(false);

  useEffect(() => {
    if (equipment) {
      setName(equipment.name || '');
      setType(equipment.type || '');
      setStatus(equipment.status || 'Active');
      setLastCleanedDate(equipment.last_cleaned_date || '');
      setIsInferred(false);
    } else {
      setName('');
      setType('');
      setStatus('Active');
      setLastCleanedDate('');
      setIsInferred(false);
    }
  }, [equipment]);

  const handleNameChange = async (e) => {
    const newName = e.target.value;
    setName(newName);

    // Attempt type inference only when adding new equipment (not editing)
    if (!equipment && newName.trim()) {
      try {
        const inferred = await inferType(newName);
        if (inferred) {
          setType(inferred);
          setIsInferred(true);
        } else {
          setIsInferred(false);
        }
      } catch (err) {
        setIsInferred(false);
      }
    }
  };

  const handleTypeChange = (e) => {
    setType(e.target.value);
    setIsInferred(false);
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!name.trim() || !type || !status || !lastCleanedDate) {
      alert('Please fill in all required fields');
      return;
    }

    onSubmit({
      name: name.trim(),
      type,
      status,
      last_cleaned_date: lastCleanedDate,
    });

    if (!equipment) {
      setName('');
      setType('');
      setStatus('Active');
      setLastCleanedDate('');
      setIsInferred(false);
    }
  };

  return (
    <form className="equipment-form" onSubmit={handleSubmit}>
      <h2>{equipment ? 'Edit Equipment' : 'Add New Equipment'}</h2>

      <div className="form-group">
        <label htmlFor="name">Name *</label>
        <input
          type="text"
          id="name"
          value={name}
          onChange={handleNameChange}
          required
        />
      </div>

      <div className="form-group">
        <label htmlFor="type">Type *</label>
        <select
          id="type"
          value={type}
          onChange={handleTypeChange}
          required
        >
          <option value="">Select type</option>
          <option value="Machine">Machine</option>
          <option value="Vessel">Vessel</option>
          <option value="Tank">Tank</option>
          <option value="Mixer">Mixer</option>
        </select>
        {isInferred && <span className="inferred-badge">Auto-filled</span>}
      </div>

      <div className="form-group">
        <label htmlFor="status">Status *</label>
        <select
          id="status"
          value={status}
          onChange={(e) => setStatus(e.target.value)}
          required
        >
          <option value="Active">Active</option>
          <option value="Inactive">Inactive</option>
          <option value="Under Maintenance">Under Maintenance</option>
        </select>
      </div>

      <div className="form-group">
        <label htmlFor="lastCleanedDate">Last Cleaned Date *</label>
        <input
          type="date"
          id="lastCleanedDate"
          value={lastCleanedDate}
          onChange={(e) => setLastCleanedDate(e.target.value)}
          required
        />
      </div>

      <div className="form-actions">
        <button type="submit">{equipment ? 'Update' : 'Add'} Equipment</button>
        {onCancel && (
          <button type="button" onClick={onCancel} className="cancel-btn">
            Cancel
          </button>
        )}
      </div>
    </form>
  );
}

export default EquipmentForm;
